<?php require_once 'header.php';$c=$medical_campaign;$related=is_array($related_campaigns??null)?$related_campaigns:array();function campaignDetailH($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function campaignDetailDate($v){return $v&&strtotime($v)?date('d/m/Y',strtotime($v)):'';}$imageUrl=XC_URL.'/uploads/medical-campaigns/'.rawurlencode($c->image_path);$fileUrl=XC_URL.'/uploads/medical-campaigns/'.rawurlencode($c->attachment_path);$dateLabel=campaignDetailDate($c->start_date).($c->end_date&&$c->end_date!==$c->start_date?' - '.campaignDetailDate($c->end_date):'');?>
